mapper.select:
select a.*, u.nick_name nickName from (
select id, family_id, host_id, start_time, end_time, live_time_sec, ticket, times
from ${dbLive}.live_host_wage_day

    host_id = #{hostId}
    and start_time  >=  #{startTime}
    and end_time  <=  #{endTime}
) a
left join ${dbLive}.live_user u on a.host_id=u.id
